import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# Custom CUDA kernel for element-wise addition (FP32)
# ----------------------------------------------------------------------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

# ----------------------------------------------------------------------
# Custom CUDA kernel for matrix multiplication (C = A @ B)
# ----------------------------------------------------------------------
gemm_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Each thread computes one element of the output matrix C.
__global__ void gemm_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < M * N) {
        int i = idx / N;          // row index of output
        int j = idx % N;          // column index of output

        float sum = 0.0f;
        for (int l = 0; l < K; ++l) {
            sum += A[i * K + l] * B[l * K + j];
        }
        C[idx] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Expect A: (M, K), B: (K, N)
    auto M = A.size(0);
    auto K = A.size(1);
    auto N = B.size(1);   # after the call B is transposed to (K, N)

    const float* a_ptr = A.data_ptr<float>();
    const float* b_ptr = B.data_ptr<float>();
    float* c_ptr = torch::empty_like(A);

    const int block_size = 256;
    const int num_blocks = (M * N + block_size - 1) / block_size;

    gemm_kernel<<<num_blocks, block_size>>>(a_ptr, b_ptr, c_ptr.data_ptr<float>(), M, K, N);

    return torch::from_blob(c_ptr, (M, N)).view(M, N).clone()
}
"""

gemm_cuda_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"
gemm_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor a, torch::Tensor b);"

matmul_cuda = load_inline(
    name="matmul_cuda",
    cpp_sources=gemm_cpp_source,
    cuda_sources=gemm_cuda_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

# ----------------------------------------------------------------------
# Optimized model
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.elementwise_add = elementwise_add
        self.matmul_cuda = matmul_cuda

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Original Model performed: return torch.matmul(A.T, B.T)
        # Our custom matmul expects (M,K) @ (K,N).  Pass the transposed inputs.
        return self.matmul_cuda(A.T, B.T)
